# Generated by Show, Don't Code from a video of a human performing the protocol.
# Review every step against the side-by-side video before running on hardware.
metadata = {'protocolName': 'PCR Setup (1 to 53 reactions) with On-Deck Thermocycling, Recovered from a Video', 'author': "Pugar Huda Mantoro, generated with Show, Don't Code", 'source': 'https://github.com/PugarHuda/show-dont-code'}
requirements = {'robotType': 'OT-2', 'apiLevel': '2.20'}

def add_parameters(parameters):
    parameters.add_int(variable_name='reactions', display_name='Reactions', description='Copies of the filmed reaction, in the next PCR plate wells; tubes are filled for all of them', default=1, minimum=1, maximum=53)
    # step 6 cycling program: default 3-step program (none legible on the bench sheet)
    parameters.add_int(variable_name='cycles', display_name='Cycles', description='Number of cycles', default=35, minimum=1, maximum=99)
    parameters.add_float(variable_name='initial1_c', display_name='Initial 1 temp', default=98.0, minimum=4.0, maximum=99.0, unit='C')
    parameters.add_int(variable_name='initial1_s', display_name='Initial 1 time', default=30, minimum=1, maximum=3600, unit='s')
    parameters.add_float(variable_name='cycle1_c', display_name='Cycle 1 temp', default=98.0, minimum=4.0, maximum=99.0, unit='C')
    parameters.add_int(variable_name='cycle1_s', display_name='Cycle 1 time', default=10, minimum=1, maximum=3600, unit='s')
    parameters.add_float(variable_name='cycle2_c', display_name='Cycle 2 temp', default=55.0, minimum=4.0, maximum=99.0, unit='C')
    parameters.add_int(variable_name='cycle2_s', display_name='Cycle 2 time', default=5, minimum=1, maximum=3600, unit='s')
    parameters.add_float(variable_name='cycle3_c', display_name='Cycle 3 temp', default=72.0, minimum=4.0, maximum=99.0, unit='C')
    parameters.add_int(variable_name='cycle3_s', display_name='Cycle 3 time', default=5, minimum=1, maximum=3600, unit='s')

def run(ctx):
    reagents = ctx.load_labware('opentrons_24_tuberack_eppendorf_1.5ml_safelock_snapcap', '5', 'reagent tubes')
    tc = ctx.load_module('thermocyclerModuleV2')
    tc.open_lid()
    dest = tc.load_labware('opentrons_96_wellplate_200ul_pcr_full_skirt')
    tips300 = [ctx.load_labware('opentrons_96_tiprack_300ul', '4')]
    p300 = ctx.load_instrument('p300_single_gen2', 'right', tip_racks=tips300)
    tips20 = [ctx.load_labware('opentrons_96_tiprack_20ul', s) for s in ['1', '2', '3'][:max(1, -(-4 * ctx.params.reactions // 96))]]
    p20 = ctx.load_instrument('p20_single_gen2', 'left', tip_racks=tips20)
    liquid0 = ctx.define_liquid('Sterile distilled water', description='20 uL drawn per reaction', display_color='#2f63d8')
    reagents['A1'].load_liquid(liquid0, min(round(20.0 * ctx.params.reactions * 1.1 + 30.0, 1), 1500.0))
    liquid1 = ctx.define_liquid('Primer1', description='1.5 uL drawn per reaction', display_color='#d9480f')
    reagents['B1'].load_liquid(liquid1, min(round(1.5 * ctx.params.reactions * 1.1 + 30.0, 1), 1500.0))
    liquid2 = ctx.define_liquid('Primer2', description='1.5 uL drawn per reaction', display_color='#0f7a5c')
    reagents['C1'].load_liquid(liquid2, min(round(1.5 * ctx.params.reactions * 1.1 + 30.0, 1), 1500.0))
    liquid3 = ctx.define_liquid('Template', description='2 uL drawn per reaction', display_color='#9c36b5')
    reagents['D1'].load_liquid(liquid3, min(round(2.0 * ctx.params.reactions * 1.1 + 30.0, 1), 1500.0))
    liquid4 = ctx.define_liquid('PrimeSTAR Max Premix', description='25 uL drawn per reaction', display_color='#e8590c')
    reagents['A2'].load_liquid(liquid4, min(round(25.0 * ctx.params.reactions * 1.1 + 30.0, 1), 1500.0))
    # step 1 [30-45s]: Add Sterile distilled water
    ctx.comment('Step 1 · video 30-45 s: Add Sterile distilled water')
    for r in range(ctx.params.reactions):
        p20.pick_up_tip()
        p20.transfer(20.0, reagents['A1'], dest.wells()[0 + 1 * r], new_tip='never')
        p20.drop_tip()
    # step 2 [64-99s]: Add Primer1
    ctx.comment('Step 2 · video 64-99 s: Add Primer1')
    for r in range(ctx.params.reactions):
        p20.pick_up_tip()
        p20.transfer(1.5, reagents['B1'], dest.wells()[0 + 1 * r], new_tip='never')
        p20.drop_tip()
    # step 3 [106-130s]: Add Primer2
    ctx.comment('Step 3 · video 106-130 s: Add Primer2')
    for r in range(ctx.params.reactions):
        p20.pick_up_tip()
        p20.transfer(1.5, reagents['C1'], dest.wells()[0 + 1 * r], new_tip='never')
        p20.drop_tip()
    # step 4 [149-173s]: Add Template
    ctx.comment('Step 4 · video 149-173 s: Add Template')
    for r in range(ctx.params.reactions):
        p20.pick_up_tip()
        p20.transfer(2.0, reagents['D1'], dest.wells()[0 + 1 * r], new_tip='never')
        p20.drop_tip()
    # step 5 [190-238s]: Add PrimeSTAR Max Premix
    ctx.comment('Step 5 · video 190-238 s: Add PrimeSTAR Max Premix')
    for r in range(ctx.params.reactions):
        p300.pick_up_tip()
        p300.transfer(25.0, reagents['A2'], dest.wells()[0 + 1 * r], new_tip='never')
        p300.drop_tip()
    # step 6 [260-266s]: Set in DNA engine
    ctx.comment('Step 6 · video 260-266 s: Set in DNA engine')
    tc.close_lid()
    tc.set_lid_temperature(105)
    tc.execute_profile(steps=[{'temperature': ctx.params.initial1_c, 'hold_time_seconds': ctx.params.initial1_s}], repetitions=1, block_max_volume=50)
    tc.execute_profile(steps=[{'temperature': ctx.params.cycle1_c, 'hold_time_seconds': ctx.params.cycle1_s}, {'temperature': ctx.params.cycle2_c, 'hold_time_seconds': ctx.params.cycle2_s}, {'temperature': ctx.params.cycle3_c, 'hold_time_seconds': ctx.params.cycle3_s}], repetitions=ctx.params.cycles, block_max_volume=50)
    tc.set_block_temperature(4)
    tc.open_lid()
